sys_ui_action.script:
try {
    // Final validation before execution
    var canExecute = true;
    var validationErrors = [];

    // Validate source funds availability
    var sourceLines = new GlideRecord('x_1962601_budget_t_realignment_line');
    sourceLines.addQuery('realignment', current.sys_id);
    sourceLines.addQuery('line_type', 'source');
    sourceLines.query();

    while (sourceLines.next()) {
        var allocation = new GlideRecord('x_1962601_budget_t_budget_allocation');
        allocation.addQuery('budget', current.budget);
        allocation.addQuery('cost_center', sourceLines.cost_center);
        allocation.query();

        if (allocation.next()) {
            var available = parseFloat(allocation.available_amount || 0);
            var required = parseFloat(sourceLines.amount || 0);

            if (required > available) {
                canExecute = false;
                validationErrors.push('Insufficient funds in ' + sourceLines.cost_center.getDisplayValue() + 
                                    ' (Required: ' + required + ', Available: ' + available + ')');
            }
        }
    }

    if (canExecute) {
        current.status = 'executed';
        current.execution_date = gs.nowDateTime();
        current.update();

        gs.addInfoMessage('Realignment executed successfully. Fund transfers have been processed.');
        action.setRedirectURL(current);
    } else {
        gs.addErrorMessage('Cannot execute realignment: ' + validationErrors.join('; '));
    }

} catch (e) {
    gs.addErrorMessage('Error executing realignment: ' + e.message);
}
